import React, { useEffect, useState } from 'react'
import axiosInstance from '../api/axiosInstance'

export function PlayerStats() {
    const [playerId, setPlayerId] = useState('')
    const [stats, setStats] = useState(null)


    async function handleStats(e) {
        e.preventDefault()
        try {
            const response = await axiosInstance.get("/totalstats/player/" + playerId)
            setStats(response.data)
            console.log(response.data);
        }
        catch (error) {
            console.log(error);

        }

    }

    return (
        <div><h1>PlayerStats</h1>
            <form onSubmit={handleStats}>
                <label> player id</label>
                <input type="text" value={playerId} onChange={(e) => { setPlayerId(e.target.value) }} />

                <button>submit</button>
            </form>

            {stats?(<div>
                <p>totalruns:{stats.totalRunScored}</p>
                <p>Balls Faced: {stats.totalBallsFaced}</p>
                <p>Wickets: {stats.totalWickets}</p>
                <p>Matches Played: {stats.matchesPlayed}</p></div>):( <p>Search for a player to see stats</p>)}



 </div> 
    )
}
